      ['bowel_observations.each_source_visible_transition', 'Inspect the source transition examples'],
      ['hernia_wall_if_relevant.contents_if_supported', 'Inspect the reported incisional-hernia contents'],
    ]],
    ['SOLID ORGANS', [
      ['gallbladder_detail.calculus_or_sludge_if_present', 'Inspect the source gallbladder sludge and wall example'],
      ['organ_common_bile_duct_if_resolved.lumen_or_duct_if_resolved', 'Compare separate ultrasound, T2 MRI and MRCP duct examples'],
      ['organ_pancreatic_tail.covered_tissue', 'Locate the source pancreatic-tail observation'],
    ]],
    ['PERITONEUM AND VESSELS', [
      ['vessel_sma_and_actual_branches.lumen_if_resolved', 'Inspect a source-labelled SMA lumen on CT and in 3D'],
      ['vessel_smv_and_actual_tributaries.lumen_if_resolved', 'Inspect a source-labelled SMV lumen on CT and in 3D'],
    ]],
  ];
  const examples = groups.filter(([heading]) => sections.includes(heading)).flatMap(([, examples]) => examples);
  if (!examples.length) return null;
  return el('section', {class: 'card', 'aria-label': 'Source evidence for this step'},
    el('h4', {}, 'Source panels for this step'),
    el('ul', {}, ...examples.map(([target, title]) => el('li', {}, el('a', {
      href: '/app/radiology/acute-abdomen-panels/index.html?target=' + encodeURIComponent('acute_abdomen.' + target),
      target: '_blank', rel: 'noopener',
    }, title)))),
    el('p', {class: 'muted'}, 'These are selected partial examples from their own source cases. The vessel CT is a separate case. Links open in a new tab so this report stays open.'));
}

const ACUTE_SOURCE_ROWS = {"anatomy-appendix": {"target": "acute_abdomen.appendix.lumen", "label": "Normal and inflamed source appendix panels"}, "anatomy-periappendiceal-fat": {"target": "acute_abdomen.appendix.periappendiceal_fat", "label": "Source periappendiceal fat change"}, "anatomy-periappendiceal-fluid": {"target": "acute_abdomen.bowel_observations.extraluminal_region", "label": "Source adjacent fluid marked +"}, "anatomy-ascending-colon": {"target": "acute_abdomen.bowel_observations.wall_thickening_site", "label": "Source ascending-colon wall change"}, "anatomy-sigmoid-colon": {"target": "acute_abdomen.bowel_observations.wall_thickening_site", "label": "Source sigmoid wall and adjacent fat examples"}, "anatomy-pancreas": {"target": "acute_abdomen.organ_pancreatic_tail.covered_tissue", "label": "Source pancreatic-tail observation"}, "anatomy-gallbladder-lumen": {"target": "acute_abdomen.gallbladder_detail.lumen", "label": "Source gallbladder lumen and sludge"}, "anatomy-gallbladder-wall": {"target": "acute_abdomen.solid_observations.abnormal_wall_or_duct_region", "label": "Source thick, striated gallbladder wall"}, "anatomy-common-bile-duct": {"target": "acute_abdomen.organ_common_bile_duct_if_resolved.lumen_or_duct_if_resolved", "label": "CBD source examples: US, T2 MRI and MRCP"}};
function rowSourcePanel(exam, section) {
  const source = exam.id === 'ra.acute-abdomen' && ACUTE_SOURCE_ROWS[section.id];
  if (!source) return null;
  const row = element('p', undefined, 'rad-source-panel-row'), link = element('a', source.label);
  link.href = '/app/radiology/acute-abdomen-panels/index.html?target=' + encodeURIComponent(source.target)
    + '&report=' + encodeURIComponent(section.id);
  link.target = '_blank'; link.rel = 'noopener';
  row.append(link); return row;
}

panelUrl(value) {
  return typeof value === 'string' && /^\/app\/radiology\/acute-abdomen-panels\/index\.html\?target=acute_abdomen\.[a-z0-9_.]+&panel=[a-z0-9-]+$/.test(value) ? value : null;
},

function panelCell(structure) {
  const cell = el('td'), entries = structure.source_panels || [];
  if (!entries.length) { cell.append(el('span', {class:'none'}, 'No reviewed local source match')); return cell; }
  const list = el('ul');
  for (const entry of entries) {
    const href = Locator.panelUrl(entry.url);
    if (!href) continue;
    list.append(el('li', {}, el('a', {href}, entry.target_name), el('small', {}, entry.label + ' · partial source example')));
  }
  cell.append(list); return cell;
}

$('panel-source-heading').hidden = !current.source_panel_rows;
$('panel-context').hidden = !current.source_panel_rows;
$('panel-context').textContent = current.source_panel_note || '';
